def parse_decimal(raw: str, what: str = "value") -> Decimal:
    """Read a field written as an ordinary decimal number, such as ``-125.00``.

    ``what`` names the field in the error message.  Text that is not a finite
    number raises :class:`LedgerParseError`; nothing here goes through ``float``.
    """
    try:
        value = Decimal(raw.strip())
    except InvalidOperation as exc:
        raise LedgerParseError(f"{what} {raw!r} is not a number") from exc
    if not value.is_finite():
        raise LedgerParseError(f"{what} {raw!r} is not a number")
    return value
